function patternInvertedPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) {
      row += ' ';
    }
    for (let k = 0; k < 2 * (n - 1 - i) + 1; k++) {
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

