function patternInvertedPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    const spaces = ' '.repeat(i);
    const stars = '*'.repeat(2 * (n - 1 - i) + 1);
    rows.push(spaces + stars);
  }
  return rows.join('\n');
}
